<script setup lang="ts">import{computed}from'vue';import{useRoute}from'vue-router';import CompanyCard from'../components/CompanyCard.vue';import{companies}from'../stores/career';import briefs from'../data/industries.json';const route=useRoute(),name=computed(()=>decodeURIComponent(String(route.params.id))),list=computed(()=>companies.filter(x=>x.industry===name.value));</script>
<template><main><RouterLink to="/industries">← 返回行业</RouterLink><div class="section-head"><div><div class="eyebrow">SECTOR BRIEF</div><h1>{{name}}</h1><p class="lede">{{(briefs as Record<string,string>)[name]}}</p></div><strong>{{list.length}} 家公司</strong></div><div class="company-grid"><CompanyCard v-for="c in list" :key="c.id" :company="c"/></div></main></template>
